// TokenPurpose distinguishes the purpose of a token in minting requests.
type TokenPurpose int32

const (
	TokenPurpose_TOKEN_PURPOSE_UNSPECIFIED TokenPurpose = 0
	// Refresh token — long-lived, used to obtain new access tokens.
	TokenPurpose_TOKEN_PURPOSE_REFRESH TokenPurpose = 1
	// Access token — short-lived, carries entitlements for a specific service.
	TokenPurpose_TOKEN_PURPOSE_ACCESS TokenPurpose = 2
	// Service token — access token scoped to a specific target service (aud).
	TokenPurpose_TOKEN_PURPOSE_SERVICE TokenPurpose = 3
	// Bootstrap token — very short-lived, used to bootstrap a child workload.
	// Parent mints this via WorkloadMint and passes it to the child process.
	// Child exchanges it with the token authority for a real access + refresh pair.
	TokenPurpose_TOKEN_PURPOSE_BOOTSTRAP TokenPurpose = 4
	// Locality token — rotated by parent, shared with all children.
	// Children present this on refresh to prove they can still reach their parent.
	TokenPurpose_TOKEN_PURPOSE_LOCALITY TokenPurpose = 5
)

